parameters.jsCode:
const picked = $json.output.repos || [];
const available = $("Extract Intake Payload").item.json.availableRepos || [];
const byUrl = new Map(available.map(r => [r.repoUrl.replace(/\/$/, ''), r]));
const merged = picked.map(p => {
  const src = byUrl.get(p.url.replace(/\/$/, '')) || {};
  return {
    ...p,
    newBranch: (p.newBranch ?? '').replace(/\s+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, ''),
    forcedClone: src.forcedClone ?? false,
    runnable: src.runnable ?? false,
    isUi: src.isUi ?? false,
    playwrightEnabled: src.playwrightEnabled ?? false,
    devServerUrl: src.devServerUrl ?? null,
    files: src.files || [],
    envVars: src.envVars || [],
  };
});
return [{ json: { repos: merged } }];
